return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Hindi','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 17:51+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'hi_IN','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'लिंगुआ फोर्ज','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'मल्टीभाषी रूटिंग, एसईओ मेटा टैग, और वर्डप्रेस के लिए एआई सामग्री उपकरण। यह भाषा पहचान, URL रूटिंग, hreflang, मेटा विवरण, और एआई-संचालित अंश, मेटा, और अनुवाद सुविधाओं को मिलाता है।','Uli Hake'=>'उली हाके','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'अनुवाद करें','Lingua Forge — Quick Translate'=>'लिंगुआ फोर्ज — त्वरित अनुवाद','Informative'=>'सूचनात्मक','Persuasive'=>'प्रेरक','Storytelling'=>'कहानी सुनाना','Technical'=>'प्राविधिक','Conversational'=>'संवादात्मक','Permission denied.'=>'अनुमति अस्वीकृत।','Cannot determine target language from slug.'=>'टग से लक्ष्य भाषा निर्धारित नहीं की जा सकी।','Invalid post type.'=>'अमान्य पोस्ट प्रकार।','Invalid or primary language.'=>'अमान्य या प्राथमिक भाषा।','Template not found or not stored in the database.'=>'टेम्पलेट नहीं मिला या डेटाबेस में संग्रहीत नहीं है।','Template has no content.'=>'टेम्पलेट में कोई सामग्री नहीं है।','No internal links found to update.'=>'अपडेट करने के लिए कोई आंतरिक लिंक नहीं मिले।','%d link updated.'=>'%d लिंक अपडेट किया गया।' . "\0" . '%d लिंक अपडेट किए गए।','No language-specific template parts found to map.'=>'मॉप करने के लिए कोई भाषा-विशिष्ट टेम्पलेट भाग नहीं मिला।','No template part references needed updating.'=>'कोई टेम्पलेट भाग संदर्भ अपडेट करने की आवश्यकता नहीं है।','%d part reference updated.'=>'%d भाग संदर्भ अपडेट किया गया।' . "\0" . '%d भाग संदर्भ अपडेट किए गए।','Invalid language.'=>'अमान्य भाषा।','Template part not found or not stored in the database.'=>'टेम्पलेट भाग नहीं मिला या डेटाबेस में संग्रहीत नहीं है।','Template part has no content.'=>'टेम्पलेट भाग में कोई सामग्री नहीं है।','No navigation references needed updating.'=>'कोई नेविगेशन संदर्भ अपडेट करने की आवश्यकता नहीं है।','%d navigation reference updated.'=>'%d नेविगेशन संदर्भ अपडेट किया गया।' . "\0" . '%d नेविगेशन संदर्भ अपडेट किए गए।','No AI provider configured.'=>'कोई एआई प्रदाता कॉन्फ़िगर नहीं किया गया।','Missing pattern name or language.'=>'पैटर्न नाम या भाषा गायब है।','Pattern not found.'=>'पैटर्न नहीं मिला।','Pattern has no content to translate.'=>'पैटर्न में अनुवाद करने के लिए कोई सामग्री नहीं है।','AI provider returned an empty response.'=>'एआई प्रदाता ने खाली प्रतिक्रिया दी।','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'पैटर्न का अनुवाद किया गया और सहेजा गया। सामग्री को अपने सीपीटी पोस्ट में ब्लॉक संपादक पैटर्न इंसर्टर के माध्यम से कॉपी करें या इसे एक पुन: प्रयोज्य ब्लॉक के रूप में शुरूआत के रूप में उपयोग करें।','Invalid template type.'=>'अमान्य टेम्पलेट प्रकार।','Template "%s" already exists.'=>'टेम्पलेट "%s" पहले से मौजूद है।','"%s" created.'=>'"%s" बनाया गया।','Invalid template part.'=>'अमान्य टेम्पलेट भाग।','Template part "%s" already exists.'=>'टेम्पलेट भाग "%s" पहले से मौजूद है।','"%1$s" created. %2$d template updated.'=>'"%1$s" बनाया गया। %2$d टेम्पलेट अपडेट किया गया।' . "\0" . '"%1$s" बनाया गया। %2$d टेम्पलेट अपडेट किए गए।','Page'=>'पृष्ठ','Single'=>'एकल','Search'=>'खोज','Search Results'=>'खोज परिणाम','Archive'=>'आर्काइव','Front Page'=>'मुखपृष्ठ','Single: %s'=>'एकल: %s','Single %s'=>'एकल %s','Archive: %s'=>'आर्काइव: %s','%s Archive'=>'%s आर्काइव','No source content found to translate.'=>'अनुवाद करने के लिए स्रोत सामग्री नहीं मिली।','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'अनुवादित। साइट संपादक में समीक्षा करें — आंतरिक लिंक, नेविगेशन URL, और टेम्प्लेट स्लग स्वचालित रूप से अपडेट नहीं होते हैं।','Navigation not found.'=>'नेविगेशन नहीं मिला।','Navigation has no content to translate.'=>'नेविगेशन में अनुवाद करने के लिए कोई सामग्री नहीं है।','"%1$s %2$s" saved.'=>'"%1$s %2$s" सहेजा गया।','Translate page…'=>'पृष्ठ का अनुवाद करें…','Generate content…'=>'सामग्री उत्पन्न करें…','AI Behaviour Preset'=>'एआई व्यवहार पूर्वनिर्धारित','Custom'=>'कस्टम','Global default (%s)'=>'वैश्विक डिफ़ॉल्ट (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'इस पृष्ठ पर अनुवाद और सामग्री निर्माण के लिए एआई पूर्वनिर्धारित को ओवरराइड करता है। साइट-व्यापी कस्टम प्रॉम्प्ट निर्देश (सेटिंग्स → व्यवहार) हर अनुरोध में जोड़े जाते हैं, इस चयन के बावजूद।','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'इस पृष्ठ पर अनुवाद और सामग्री निर्माण के लिए एआई पूर्वनिर्धारित को ओवरराइड करता है। सभी अन्य सुविधाएँ हमेशा वैश्विक पूर्वनिर्धारित का उपयोग करती हैं।','Close'=>'बंद करें','Translate missing'=>'लापता अनुवाद करें','From'=>'से','Retranslate'=>'पुनः अनुवाद करें','Translating…'=>'अनुवाद हो रहा है…','Retranslating…'=>'पुनः अनुवाद हो रहा है…','✓ Done'=>'✓ पूरा हुआ','Error'=>'त्रुटि','Navigation posts are translated via the Router tab, not this button.'=>'नेविगेशन पोस्ट राउटर टैब के माध्यम से अनुवादित होते हैं, इस बटन के माध्यम से नहीं।','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'पोस्ट प्रकार "%s" के लिए अनुवाद बनाना एक सक्रिय एकीकरण की आवश्यकता है। कृपया सुनिश्चित करें कि आवश्यक एकीकरण स्थापित और सक्रिय है।','No %s version found in this translation group.'=>'इस अनुवाद समूह में कोई %s संस्करण नहीं मिला।','AI Usage'=>'एआई उपयोग','Today'=>'आज','Last 7 days'=>'पिछले 7 दिन','Last 30 days'=>'पिछले 30 दिन','All time'=>'सभी समय','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'विशेषता, प्रदाता, और मॉडल द्वारा टोकन खपत को रोल किया गया। हर सफल एआई कॉल पर रिकॉर्ड किया जाता है; परीक्षण कनेक्शन पिंग को जानबूझकर बाहर रखा गया है ताकि वे कुल को प्रभावित न करें। अंतर्निहित तालिका दैनिक सारांश बनाती है — इसे देखने के लिए नीचे एक विंडो चुनें।','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'अभी तक कोई एआई उपयोग रिकॉर्ड नहीं हुआ है। एक संपादक जब अनुवाद करता है, मेटा विवरण उत्पन्न करता है, या किसी अन्य एआई सुविधा का उपयोग करता है, तो कुल यहां दिखाई देंगे।','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'चयनित विंडो (%s) में कोई एआई उपयोग रिकॉर्ड नहीं हुआ है। ऊपर एक व्यापक सीमा चुनें।','Feature'=>'विशेषता','Provider'=>'प्रदाता','Model'=>'मॉडल','Requests'=>'अनुरोध','Input tokens'=>'इनपुट टोकन','Output tokens'=>'आउटपुट टोकन','Total tokens'=>'कुल टोकन','Total'=>'कुल','API Keys'=>'एपीआई कुंजी','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'कुंजी को AES-256-CBC के साथ एन्क्रिप्ट किया जाता है इससे पहले कि वह वर्डप्रेस डेटाबेस में संग्रहित हो। एन्क्रिप्शन रहस्य आपके वर्डप्रेस ऑथ सॉल्ट्स (wp-config.php) से लिया जाता है, इसलिए प्लेनटेक्स्ट कुंजी कभी भी डेटाबेस को नहीं छूती।','API Key'=>'एपीआई कुंजी','Paste your API key…'=>'अपनी एपीआई कुंजी चिपकाएँ…','✓ Configured'=>'✓ कॉन्फ़िगर किया गया','✗ Not configured'=>'✗ कॉन्फ़िगर नहीं किया गया','Test connection'=>'कनेक्शन का परीक्षण करें','Leave blank to keep the existing key. Enter a new value to replace it.'=>'खाली छोड़ें ताकि मौजूदा कुंजी बनी रहे। इसे बदलने के लिए एक नई मान दर्ज करें।','Remove stored key'=>'संग्रहीत कुंजी हटाएँ','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'यह कुंजी वर्तमान में एक सर्वर %s द्वारा प्रदान की जा रही है और इसे यहाँ से नहीं हटाया जा सकता। इसे ओवरराइड करने के लिए ऊपर एक नई कुंजी दर्ज करें।','environment variable'=>'पर्यावरण चर','PHP constant'=>'PHP स्थिरांक','Alternative (server-side):'=>'वैकल्पिक (सर्वर-साइड):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'आप कुंजी को स्थिरांक या पर्यावरण चर के रूप में भी परिभाषित कर सकते हैं (जैसे wp-config.php में)। ये स्रोत स्वचालित रूप से तब उपयोग किए जाते हैं जब कोई डेटाबेस कुंजी संग्रहीत नहीं होती।','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'कस्टम एन्क्रिप्शन सीक्रेट का उपयोग करने के लिए (डेराइव्ड wp_salt मान के बजाय), इसे wp-config.php में जोड़ें:','Unknown provider.'=>'अज्ञात प्रदाता।','No API key configured for this provider.'=>'इस प्रदाता के लिए कोई API कुंजी कॉन्फ़िगर नहीं की गई है।','Could not instantiate the provider.'=>'प्रदाता को स्थापित नहीं किया जा सका।','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'प्रदाता कोई टेक्स्ट वापस नहीं किया। विस्तृत विफलता कारण के लिए WordPress त्रुटि लॉग जांचें।','Behavior'=>'व्यवहार','Block Editor'=>'ब्लॉक संपादक','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge डिफ़ॉल्ट रूप से दो Gutenberg विशेषताओं को प्रतिबंधित करता है ताकि भाषाओं में संपादकीय व्यवहार सुसंगत रहे। जब आप पूर्ण Gutenberg / FSE क्षमताओं की आवश्यकता हो, तो यहाँ ऑप्ट इन करें।','Block locking'=>'ब्लॉक लॉकिंग','Allow editors to lock individual blocks'=>'संपादकों को व्यक्तिगत ब्लॉक लॉक करने की अनुमति दें','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Gutenberg\'s canLockBlocks को पुनः सक्षम करता है। संपादकीय टेम्प्लेट के लिए उपयोगी है जो योगदानकर्ताओं को विशिष्ट ब्लॉक को स्थानांतरित या हटाने से रोकने की आवश्यकता होती है।','Template mode'=>'टेम्प्लेट मोड','Allow Gutenberg template-editing mode on post screens'=>'पोस्ट स्क्रीन पर Gutenberg टेम्प्लेट-एडिटिंग मोड की अनुमति दें','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'supportsTemplateMode को पुनः सक्षम करता है। यह पूर्ण-साइट-एडिटिंग वर्कफ़्लोज़ के लिए मुख्य है जहां पोस्ट-स्तर टेम्प्लेट ओवरराइड इरादतन होते हैं।','Compliance Preset'=>'अनुपालन पूर्वसेट','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'कानूनी, नियामक, चिकित्सा, या तकनीकी सामग्री के लिए सख्त संरक्षण मोड। जब चालू हो, तो हर AI सुविधा कम सैंपलिंग तापमान का उपयोग करती है और अपने सिस्टम प्रॉम्प्ट में नीचे दी गई परिशिष्ट जोड़ती है — शब्दावली, लेख संख्या, इकाइयां, ब्रांड नाम, और नियामक भाषा को शब्दशः संरक्षित किया जाता है, न कि परिभाषित।','Global AI preset'=>'वैश्विक AI पूर्वसेट','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, प्रति सुविधा','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'साइट-व्यापी सभी सुविधाओं के लिए डिफ़ॉल्ट AI व्यवहार सेट करता है। व्यक्तिगत पोस्ट इसको ओवरराइड कर सकते हैं, जैसे अनुवाद और सामग्री निर्माण, Lingua Forge मेटा बॉक्स के माध्यम से।','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'मानक प्रत्येक सुविधा के अपने ट्यून किए गए तापमान का उपयोग करता है: अनुवाद T=0.2 (सटीक), त्वरित अनुवाद T=0.4, सामग्री निर्माता T=0.6 (रचनात्मक)। अन्य पूर्वसेट सभी सुविधाओं पर एकल स्थिर तापमान लागू करते हैं।','Technical / Scientific instructions'=>'तकनीकी / वैज्ञानिक निर्देश','Legal / Compliance instructions'=>'कानूनी / अनुपालन निर्देश','Creative / Marketing instructions'=>'रचनात्मक / विपणन निर्देश','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'डिफ़ॉल्ट का उपयोग करने के लिए खाली छोड़ें। सहेजने पर एक सहेजी गई ओवरराइड को हटाने से डिफ़ॉल्ट पुनः स्थापित हो जाता है।','View built-in default'=>'निर्मित डिफ़ॉल्ट देखें','Translation Memory'=>'अनुवाद स्मृति','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'ब्लॉक स्तर पर अनुवादित समकक्षों को कैश करें ताकि पुन: प्रयोज्य सामग्री (साझा फुटर, साइडबार, अकॉर्डियन, भारी कानूनी अनुभाग) हर बार API कॉल न करें। सक्षम होने पर, अनुवाद प्रवाह प्रत्येक पोस्ट को ब्लॉकों में पार्स करता है, प्रत्येक ब्लॉक को कैश में देखता है, और केवल अनकैश्ड ब्लॉकों को एक बैच अनुरोध में AI को भेजता है। शब्दकोश संपादन और अनुपालन पूर्वसेट परिवर्तन स्वचालित रूप से प्रभावित कैश किए गए अनुवादों को अमान्य कर देते हैं। आँकड़े देखें और कैश साफ़ करें।','Enable block-level translation cache reuse across posts'=>'ब्लॉक-स्तर अनुवाद कैश पुन: उपयोग को पोस्ट के बीच सक्षम करें','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'वर्तमान में उन पोस्ट के लिए छोड़ दिया गया है जो ब्लॉक-टिप्पणी विशेषता प्लेसहोल्डर (wp:details सारांश क्षेत्र आदि) का उपयोग करते हैं — वे मौजूदा एकल-आह्वान अनुवाद पथ पर जाते हैं।','General'=>'सामान्य','Light'=>'हल्का','Meta Description, Excerpt Generator'=>'मेटा विवरण, सारांश जनरेटर','Quality'=>'गुणवत्ता','Translation, Content Generator'=>'अनुवाद, सामग्री निर्माता','Active Provider'=>'सक्रिय प्रदाता','Currently inherited from the %s constant. Selecting a value here will override it.'=>'वर्तमान में %s स्थिरांक से विरासत में मिला है। यहाँ मान चुनने से यह ओवरराइड हो जाएगा।','Models'=>'मॉडल','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'विशेषताएँ दो स्तरों में समूहित हैं। प्रत्येक स्तर और प्रदाता के लिए सटीक मॉडल पहचानकर्ता दर्ज करें। एक फ़ील्ड खाली छोड़ें ताकि डिफ़ॉल्ट का उपयोग हो सके। केवल सक्रिय प्रदाता के मॉडल रनटाइम पर कॉल किए जाते हैं — यदि आप स्विच करने की योजना बना रहे हैं तो अन्य को पहले से कॉन्फ़िगर करें।','active'=>'सक्रिय','overridden'=>'ओवरराइड किया गया','Tip: to reset a model to the built-in default, clear the field and save.'=>'टिप: एक मॉडल को डिफ़ॉल्ट में रीसेट करने के लिए, फ़ील्ड साफ़ करें और सहेजें।','Glossary'=>'शब्दावली','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'प्रति भाषा जोड़ी के लिए उपयोगकर्ता-प्रबंधित शब्दावली तालिका। प्रविष्टियों को अनुवाद प्रणाली प्रॉम्प्ट में जोड़ा जाता है ताकि AI लगातार वांछित शब्दों का उपयोग करे — क्षेत्रीय शब्दावली ("kWp", "PPA", "interconnection point"), ब्रांड नाम जिन्हें अनुवादित नहीं किया जाना चाहिए, और मानकीकृत नियमावली वाक्यांश। दोनों भाषा क्षेत्रों को वैकल्पिक है: "स्रोत भाषा" को खाली छोड़ें ताकि यह प्रविष्टि किसी भी भाषा से अनुवाद करने पर लागू हो; "लक्ष्य भाषा" को खाली छोड़ें ताकि यह सभी लक्षित भाषाओं पर एक साथ लागू हो।','Glossary entry added.'=>'शब्दावली प्रविष्टि जोड़ी गई।','Glossary entry removed.'=>'शब्दावली प्रविष्टि हटा दी गई।','Could not add entry: source term and target term are required.'=>'प्रविष्टि जोड़ने में असमर्थ: स्रोत शब्द और लक्ष्य शब्द आवश्यक हैं।','Could not save the glossary entry.'=>'शब्दावली प्रविष्टि सहेजने में असमर्थ।','Source language'=>'स्रोत भाषा','— Any —'=>'— कोई भी —','Target language'=>'लक्ष्य भाषा','— Any target —'=>'— कोई भी लक्ष्य —','Filter'=>'फ़िल्टर','Reset'=>'रीसेट','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'वर्तमान फ़िल्टर से मेल खाने वाली कोई भी शब्दावली प्रविष्टि नहीं है। सभी प्रविष्टियों को देखने के लिए फ़िल्टर साफ़ करें, या नीचे एक नई प्रविष्टि जोड़ें।','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'अभी तक कोई शब्दावली प्रविष्टि नहीं है। अनुवाद में शब्दावली लागू करने के लिए नीचे एक जोड़ें।','Source term'=>'स्रोत शब्द','Target term'=>'लक्ष्य शब्द','Source lang'=>'स्रोत भाषा','Target lang'=>'लक्ष्य भाषा','Notes'=>'टिप्पणियाँ','any'=>'कोई भी','Delete this glossary entry?'=>'क्या आप इस शब्दावली प्रविष्टि को हटाना चाहते हैं?','Delete'=>'हटाएँ','Add new entry'=>'नई प्रविष्टि जोड़ें','The phrase as it appears in the source text.'=>'स्रोत पाठ में जैसा दिखाई देता है।','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'अनुवाद में ऐसा ही दिखना चाहिए। AI को निर्देशित करने के लिए स्रोत शब्द के समान मान टाइप करें ताकि इसे शाब्दिक रूप से संरक्षित किया जाए।','— Any source language —'=>'— कोई भी स्रोत भाषा —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'ब्रांड नाम और भाषा-अज्ञेय शब्दावली के लिए खाली छोड़ें जिन्हें अनुवाद से कोई फर्क नहीं पड़ता।','— Any target language —'=>'— कोई भी लक्ष्य भाषा —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'इस प्रविष्टि को सभी लक्षित भाषाओं पर लागू करने के लिए खाली छोड़ें — ब्रांड नाम, संक्षेपण, और ऐसे शब्द जो हर अनुवाद में शाब्दिक रूप से संरक्षित रहना चाहिए।','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'संपादकों के लिए वैकल्पिक संदर्भ (जैसे "ASIC = एप्लिकेशन-विशिष्ट इंटीग्रेटेड सर्किट; तकनीकी संदर्भ में अंग्रेजी में संरक्षित करें")।','Add entry'=>'प्रविष्टि जोड़ें','Limits'=>'सीमाएँ','Authors and above (edit_published_posts)'=>'लेखक और ऊपर (संपादित_प्रकाशित_पोस्ट)','Contributors and above — default (edit_posts)'=>'योगदानकर्ता और ऊपर — डिफ़ॉल्ट (संपादित_पोस्ट)','Editors and above (edit_others_posts)'=>'संपादक और ऊपर (अन्य_पोस्ट_संपादित करें)','Administrators only (manage_options)'=>'केवल व्यवस्थापक (प्रबंध_विकल्प)','AI Limits & Security'=>'AI सीमाएँ और सुरक्षा','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'साइट कितनी AI उपयोग कर सकती है इसकी सीमा निर्धारित करें और कौन से उपयोगकर्ता भूमिकाएँ भुगतान किए गए AI कॉल कर सकती हैं, इसे प्रतिबंधित करें। यह प्रति-उपयोगकर्ता दर सीमा (30 अनुरोध / मिनट, हार्डकोडेड) के ऊपर बैठता है जो पहले से ही एकल-उपयोगकर्ता रनवे लूप से सुरक्षा करता है।','Daily request limit'=>'दैनिक अनुरोध सीमा','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'UTC दिन के लिए साइट-व्यापी AI अनुरोध सीमा (टूलबार अनुवाद और ब्लॉक संशोधन दोनों को गिनता है)। काउंटर UTC मध्यरात्रि पर रीसेट होता है। इसे अक्षम करने के लिए 0 सेट करें।','Minimum role'=>'न्यूनतम भूमिका','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'AI सुविधाओं को ट्रिगर करने के लिए अनुमति प्राप्त सबसे कम WordPress क्षमता। इसे मजबूत करने से योगदानकर्ताओं या परीक्षण खातों को भुगतान किए गए AI कॉल चलाने से रोका जा सकता है। प्रत्येक सुविधा के लिए override करें linguaforge_required_capability फ़िल्टर के माध्यम से।','Translation Limits'=>'अनुवाद सीमाएँ','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'यह नियंत्रित करें कि कितना कंटेंट AI को भेजा जाए और प्रतिक्रिया कितनी बड़ी हो सकती है। यदि बड़ी पृष्ठें कट रही हैं तो इन मानों को बढ़ाएँ; लागत कम करने के लिए इन्हें घटाएँ।','Model tier'=>'मॉडल स्तर','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'गुणवत्ता (डिफ़ॉल्ट — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'प्रकाश (तेज और लागत-कुशल — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'पूर्ण-पृष्ठ अनुवाद के लिए कौन सा मॉडल स्तर उपयोग करें। गुणवत्ता ऊपर दिए गए Models तालिका में कॉन्फ़िगर किए गए मॉडल का उपयोग करता है और सटीक, लंबी-फॉर्म अनुवाद के लिए अनुशंसित है। केवल यदि गति या लागत प्राथमिकता है और सामग्री छोटी है तो ही Light पर स्विच करें।','Max output tokens'=>'अधिकतम आउटपुट टोकन','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'एकल अनुवाद प्रतिक्रिया में AI द्वारा उत्पन्न अधिकतम टोकन की संख्या। यदि अनुवाद चुपचाप समाप्त हो रहा है, तो इस मान को बढ़ाएँ। डिफ़ॉल्ट: 16,000।','Max input characters'=>'अधिकतम इनपुट वर्ण','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'पोस्ट सामग्री की अधिकतम संख्या जो AI को भेजी जाती है। 0 का अर्थ है कोई सीमा नहीं — पूरी सामग्री हमेशा भेजी जाती है (सिफारिश की गई)। यदि आपका प्रदाता टाइट संदर्भ विंडो रखता है तो ही गैर-शून्य मान सेट करें। जब सामग्री को ट्रिम किया जाता है तो PHP त्रुटि लॉग में चेतावनी लिखी जाती है।','Quick Translation'=>'त्वरित अनुवाद','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'त्वरित अनुवाद का उपयोग स्निपेट/चंक मोड के लिए किया जाता है — टूलबार, संपादक, या ब्लॉक पॉपओवर से मांग पर छोटे अंशों का अनुवाद। यह पूर्ण-पृष्ठ अनुवाद से अलग, हल्के कॉन्फ़िगरेशन का उपयोग करता है ताकि प्रतिक्रियाएँ तेज़ और लागत-कुशल रहें।','Light (default — fast and cost-effective)'=>'हल्का (डिफ़ॉल्ट — तेज़ और लागत-कुशल)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'गुणवत्ता (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'हल्का स्तर तेज़ मॉडल का उपयोग करता है जो ऊपर दिए गए मॉडल तालिका में कॉन्फ़िगर किया गया है (डिफ़ॉल्ट: Haiku / Flash)। यदि आप स्निपेट के लिए पूर्ण-पृष्ठ मोड जैसी अनुवाद सटीकता चाहते हैं तो गुणवत्ता पर स्विच करें।','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'प्रति त्वरित अनुवाद AI द्वारा उत्पादित अधिकतम टोकन। डिफ़ॉल्ट: 2,000।','Maximum characters accepted from the input field. Default: 8 000.'=>'इनपुट फ़ील्ड से स्वीकार किए गए अधिकतम वर्ण। डिफ़ॉल्ट: 8,000।','Content Generator'=>'सामग्री जनरेटर','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'AI कंटेंट जनरेटर सुविधा के लिए टोकन बजट और इनपुट सीमाओं को नियंत्रित करता है। अंतर्निहित डिफ़ॉल्ट का उपयोग करने के लिए फ़ील्ड खाली छोड़ें।','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'प्रति पीढ़ी रन AI द्वारा उत्पादित अधिकतम टोकन। यदि पूर्ण लेख कट रहे हैं तो इसे बढ़ाएँ। डिफ़ॉल्ट: 8,192।','Max hints characters'=>'संकेतों के अधिकतम वर्ण','Maximum characters read from the Hints field. Default: 2 000.'=>'संकेत फ़ील्ड से पढ़े गए अधिकतम वर्ण। डिफ़ॉल्ट: 2,000।','Max context characters'=>'अधिकतम संदर्भ वर्ण','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'जब संकेत प्रदान नहीं किए जाते हैं तो AI को पास किया गया मौजूदा पोस्ट सामग्री का अधिकतम वर्ण। डिफ़ॉल्ट: 6,000।','Maintenance'=>'रखरखाव','Language Overrides'=>'भाषा ओवरराइड्स','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'विशिष्ट स्थानीयकरण के लिए तृतीय-पक्ष प्लगइन स्ट्रिंग्स को ओवरराइड करने के लिए संकलित .mo फ़ाइलें अपलोड करें — उदाहरण के लिए, एक कस्टम VikBooking अनुवाद जो "कमरा" के बजाय "अपार्टमेंट" का उपयोग करता है। फ़ाइलें WordPress नामकरण सम्मेलन का पालन करनी चाहिए: {textdomain}-{locale}.mo (जैसे vikbooking-ca.mo)। इन्हें अपलोड्स फ़ोल्डर में संग्रहित किया जाता है और प्लगइन अपडेट के दौरान भी रहते हैं।','Override file uploaded successfully.'=>'ओवरराइड फ़ाइल सफलतापूर्वक अपलोड की गई।','Override file deleted.'=>'ओवरराइड फ़ाइल हटा दी गई।','No file was selected.'=>'कोई फ़ाइल चयनित नहीं की गई।','Only .mo files are accepted.'=>'केवल .mo फ़ाइलें स्वीकार की जाती हैं।','The upload failed — please try again.'=>'अपलोड विफल रहा — कृपया पुनः प्रयास करें।','Could not save the file. Check that the uploads folder is writable.'=>'फ़ाइल सहेज नहीं सकी। जांचें कि अपलोड फ़ोल्डर लिखने योग्य है या नहीं।','Invalid filename.'=>'अमान्य फ़ाइल नाम।','Security check failed — file path is not permitted.'=>'सुरक्षा जांच विफल — फ़ाइल पथ अनुमति प्राप्त नहीं है।','An unknown error occurred.'=>'एक अज्ञात त्रुटि हुई।','Text domain / locale'=>'टेक्स्ट डोमेन / स्थानीयकरण','Files'=>'फ़ाइलें','Size'=>'आकार','Delete all files for this override (both .mo and .po)?'=>'क्या इस ओवरराइड के लिए सभी फ़ाइलें हटा दी जाएं (दोनों .mo और .po)?','No override files uploaded yet.'=>'अभी तक कोई ओवरराइड फ़ाइलें अपलोड नहीं की गई हैं।','Upload .mo file'=>'.mo फ़ाइल अपलोड करें','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'संकलित .mo फ़ाइलें ही स्वीकार की जाती हैं। फ़ाइल नाम {textdomain}-{locale}.mo के पैटर्न का पालन करना चाहिए। एक ही नाम की फ़ाइल अपलोड करने से वह प्रतिस्थापित हो जाएगी।','Upload Override'=>'ओवरराइड अपलोड करें','Loco Translate — Copy to Safe Storage'=>'Loco Translate — सुरक्षित संग्रह में कॉपी करें','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate अपनी कस्टम अनुवादों को wp-content/languages/loco/ में संग्रहित करता है — एक स्थान जिसे WP कोर अपडेट, प्लगइन पुनःइंस्टॉल, या यदि Loco Translate स्वयं हटा दिया जाए तो चुपचाप मिटाया जा सकता है। यहाँ फ़ाइलें कॉपी करने से वे Lingua Forge i18n-overrides निर्देशिका में चली जाती हैं, जो इन सभी घटनाओं के दौरान बनी रहती है और हर अनुरोध पर स्वचालित रूप से लोड हो जाती है।','File copied to safe storage successfully.'=>'सुरक्षित संग्रह में फ़ाइल सफलतापूर्वक कॉपी की गई।','Source file not found.'=>'स्रोत फ़ाइल नहीं मिली।','Could not copy the file. Check that the uploads folder is writable.'=>'फ़ाइल कॉपी नहीं कर सका। जांचें कि अपलोड फ़ोल्डर लिखने योग्य है या नहीं।','Invalid file reference.'=>'अमान्य फ़ाइल संदर्भ।','Type'=>'प्रकार','✓ In safe storage'=>'✓ सुरक्षित संग्रह में','Copy to safe storage'=>'सुरक्षित संग्रह में कॉपी करें','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'अभी तक कोई कस्टम Loco Translate फ़ाइलें नहीं मिली हैं। जब आप Loco Translate में अनुवाद सहेजते हैं तो ये यहाँ दिखाई देती हैं।','AI Cache'=>'AI कैश','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'Lingua Forge AI-जनित अनुवाद, मेटा विवरण, अंश, और जनरेटेड सामग्री को कैश करता है ताकि अपरिवर्तित इनपुट्स से भुगतान API कॉल पुनः ट्रिगर न हो। कैश प्रविष्टियों को स्वचालित रूप से अमान्य कर दिया जाता है जब उनके इनपुट बदलते हैं। कैश को मैनुअल रूप से साफ़ करें ताकि डेटाबेस स्थान खाली हो सके, प्रदाता बदलने या प्रॉम्प्ट टेम्प्लेट संपादित करने के बाद पुनः सिंक करें, या कैश-संबंधित समस्या का समाधान करें।','AI cache cleared. %d entry was removed.'=>'AI कैश साफ़ कर दी गई। %d प्रविष्टि हटा दी गई।' . "\0" . 'AI कैश साफ़ कर दी गई। %d प्रविष्टियाँ हटा दी गईं।','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'क्या सभी कैश्ड AI परिणामों को साफ़ कर दें? भविष्य की अनुरोध नई API कॉल ट्रिगर करेंगी जब तक कि कैश पुनः बन न जाए।','Clear AI Cache'=>'एआई कैश साफ़ करें','Debug Files'=>'डिबग फ़ाइलें','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'जब डिबग लॉगिंग सक्षम होती है (नीचे टॉगल के माध्यम से या wp-config.php में LINGUAFORGE_AI_DEBUG को परिभाषित करके), अनुवाद और FSE टेम्प्लेट अनुवाद सुविधाएँ अपने कच्चे AI प्रॉम्प्ट और प्रतिक्रियाओं को समस्या निवारण के लिए डिस्क पर लिखती हैं। इस अनुभाग का उपयोग उस आउटपुट की निगरानी करने के लिए करें और जब आप आवश्यक हो तो इसे साफ़ करें — फ़ाइलें बड़े पृष्ठों पर जल्दी बढ़ सकती हैं। टारगेट डायरेक्टरी को linguaforge_debug_dir फ़िल्टर के माध्यम से कॉन्फ़िगर करें।','Debug files cleared. %d file was removed.'=>'डिबग फ़ाइलें साफ़ कर दी गईं। %d फ़ाइल हटा दी गई।' . "\0" . 'डिबग फ़ाइलें साफ़ कर दी गईं। %d फ़ाइलें हटा दी गईं।','Debug logging enabled.'=>'डिबग लॉगिंग सक्षम।','Debug logging disabled.'=>'डिबग लॉगिंग अक्षम।','Debug logging'=>'डिबग लॉगिंग','Write AI prompts and responses to disk for troubleshooting'=>'समस्या निवारण के लिए AI प्रॉम्प्ट और प्रतिक्रियाएँ डिस्क पर लिखें','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php में LINGUAFORGE_AI_DEBUG स्थिरांक द्वारा जबरदस्ती चालू। इस टॉगल को नियंत्रित करने के लिए उस लाइन को हटा दें।','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php में LINGUAFORGE_AI_DEBUG स्थिरांक द्वारा जबरदस्ती बंद। इस टॉगल को नियंत्रित करने के लिए उस लाइन को हटा दें।','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'फ़ाइलें नीचे दिए गए निर्देशिका में land करती हैं। अनुवाद संबंधी मुद्दों का निदान करने के लिए उपयोगी — जब आप आवश्यक हो तो बंद कर दें ताकि फ़ाइलें जमा न हों। आप इसे wp-config.php से भी नियंत्रित कर सकते हैं `define( \'LINGUAFORGE_AI_DEBUG\', true );` के साथ, जो टॉगल को ओवरराइड करता है।','Currently:'=>'वर्तमान में:','✓ Enabled'=>'✓ सक्षम','✗ Disabled'=>'✗ अक्षम','Directory'=>'डायरेक्टरी','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'डिबग आउटपुट को एक गैर-सार्वजनिक स्थान पर पुनर्निर्देशित करने के लिए linguaforge_debug_dir के साथ फ़िल्टर करें।','.txt file(s) in the directory'=>'.txt फ़ाइल(ें) इस निर्देशिका में','Save Debug Setting'=>'डिबग सेटिंग सहेजें','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'डिबग निर्देशिका में सभी .txt फ़ाइलें हटाएँ? निर्देशिका स्वयं बनी रहेगी ताकि भविष्य में डिबग लिखावट साफ़ तरीके से हो सके।','Clear Debug Files'=>'डिबग फ़ाइलें साफ़ करें','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'प्रति-ब्लॉक अनुवाद कैश साझा किया गया है। सेटिंग्स → व्यवहार में ऑन/ऑफ़ कॉन्फ़िगर करें। नीचे दी गई सांख्यिकी दिखाती है कि वर्तमान में क्या कैश है; साफ़ करने से हर ब्लॉक को अगले अनुरोध पर फिर से अनुवादित किया जाएगा (मॉडल अपग्रेड करने या डेटाबेस स्थान पुनः प्राप्त करने के लिए उपयोगी)।','Translation Memory cleared. %d cached block was removed.'=>'अनुवाद स्मृति साफ़ कर दी गई। %d कैश्ड ब्लॉक हटा दिया गया।' . "\0" . 'अनुवाद स्मृति साफ़ कर दी गई। %d कैश्ड ब्लॉक हटा दिए गए।','Status'=>'स्थिति','— toggle in Settings → Behavior.'=>'— सेटिंग्स → व्यवहार में टॉगल।','Cached blocks'=>'कैश्ड ब्लॉक','Cumulative cache hits'=>'सामूहिक कैश हिट्स','(avg %.1f hits/block)'=>'(औसत %.1f हिट्स/ब्लॉक)','Oldest entry'=>'सबसे पुराना प्रविष्टि','Newest entry'=>'सबसे नई प्रविष्टि','Approximate size'=>'अनुमानित आकार','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'संपूर्ण अनुवाद स्मृति साफ़ करें? भविष्य के अनुवाद उन्हें पुनः बनाना शुरू कर देंगे।','Clear Translation Memory'=>'अनुवाद स्मृति साफ़ करें','Uninstall Behaviour'=>'अस्थायी व्यवहार','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'जब व्यवस्थापक प्लगइन को Plugins → Installed Plugins → Delete से हटाता है तो क्या होता है, इसे नियंत्रित करता है। प्लगइन सेटिंग्स और AI कैशेस हमेशा हटा दी जाती हैं। भाषा असाइनमेंट और अनुवाद संबंध डिफ़ॉल्ट रूप से रखे जाते हैं ताकि अनजाने में अनइंस्टॉल या पुनः इंस्टॉल करने पर वे वहीं से शुरू हो सकें।','Uninstall setting saved.'=>'अस्थायी व्यवहार सेटिंग सहेजी गई।','Delete content data on uninstall'=>'अस्थायी रूप से सामग्री डेटा हटाएँ','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'जब प्लगइन अनइंस्टॉल किया जाता है, तो भाषा असाइनमेंट, अनुवाद संबंध, मेटा विवरण, शब्दकोश, और अनुवाद स्मृति भी हटा दी जाती है।','Warning:'=>'चेतावनी:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'यदि चेक किया गया है, तो प्लगइन को अनइंस्टॉल करने पर सभी भाषा असाइनमेंट, अनुवाद संबंध, मेटा विवरण, प्रति-पृष्ठ पूर्व सेटिंग्स, AI शब्दकोश, और अनुवाद स्मृति स्थायी रूप से हटा दी जाएगी। इसे वापस नहीं लिया जा सकता। जब तक आप पूरी तरह से बहुभाषी समर्थन को साइट से हटा रहे हैं, तब तक अनचेक छोड़ दें।','Save Uninstall Setting'=>'अस्थायी सेटिंग सहेजें','Router'=>'राउटर','Primary language saved.'=>'प्राथमिक भाषा सहेजी गई।','Permalink rules flushed successfully.'=>'Permalink नियम सफलतापूर्वक फ्लश किए गए।','Primary Language'=>'प्राथमिक भाषा','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'प्राथमिक भाषा हमेशा आपकी साइट के रूट पर सेवा की जाती है — पथ मोड में कोई URL उपसर्ग नहीं, उपडोमेन मोड में कोई भाषा उपडोमेन नहीं। अन्य सभी भाषाएँ या तो /lang/ पथ उपसर्ग (जैसे example.com/de/) का उपयोग करती हैं या भाषा उपडोमेन (जैसे de.example.com), URL संरचना सेटिंग के आधार पर।','Primary language'=>'प्राथमिक भाषा','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'प्राथमिक भाषा बदलने के बाद, URL रूटिंग को अपडेट करने के लिए permalinks (सेक्शन नीचे) को फ्लश करें।','URL structure'=>'URL संरचना','Path prefix — example.com/de/'=>'पथ उपसर्ग — example.com/de/','Subdomain — de.example.com/'=>'उपडोमेन — de.example.com/','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'उपडोमेन मोड को आपकी वेब सर्वर को सभी भाषा उपडोमेन (जैसे de.example.com) को इस वर्डप्रेस इंस्टॉलेशन की ओर संकेत करने की आवश्यकता होती है। मोड बदलने के बाद, permalink नियमों को फ्लश करें और किसी भी कैश को साफ करें। यदि आपका होम URL www शामिल करता है (जैसे www.example.com), तो lf_base_domain फ़िल्टर का उपयोग करके बेस एपेक्स डोमेन सेट करें ताकि उपडोमेन सही ढंग से बनाए जा सकें।','Browser language redirect'=>'ब्राउज़र भाषा पुनः निर्देशित','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'ब्राउज़र के Accept-Language हेडर के आधार पर आगंतुकों को उनकी पसंदीदा भाषा में पुनः निर्देशित करें','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'जब सक्षम हो, तो पहली बार आने वाले आगंतुक जिनके पास कोई भाषा कुकी नहीं है और URL में कोई भाषा उपसर्ग नहीं है, उन्हें सबसे मिलते-जुलते भाषा संस्करण पर पुनः निर्देशित किया जाता है। यदि ब्राउज़र की पसंदीदा भाषा सक्रिय राउटर भाषाओं में से नहीं है, तो पुनः निर्देशित नहीं किया जाता है। जब कोई आगंतुक स्विचर के माध्यम से एक भाषा चुनता है, तो कुकी प्राथमिकता लेती है और भविष्य की सभी यात्राओं पर ब्राउज़र हेडर को नजरअंदाज किया जाता है।','Save Router Settings'=>'राउटर सेटिंग्स सहेजें','Flush Permalinks'=>'Permalinks को फ्लश करें','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'वर्डप्रेस रीव्राइट नियमों को पुनः जेनरेट करता है ताकि URL उपसर्ग, भाषा-विशिष्ट स्लग, और आर्काइव रीव्राइट्स सभी सिंक में हों। मुख्य भाषा बदलने या नई भाषा समर्थन जोड़ने के बाद आवश्यक।','Flush Permalink Rules'=>'Permalink नियमों को फ्लश करें','Active Languages'=>'सक्रिय भाषाएँ','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'राउटर को वर्तमान में ज्ञात भाषाएँ (स्थापित वर्डप्रेस लोकल पैक और मुख्य भाषा से प्राप्त)। अधिक भाषाओं के लिए नीचे दिए गए अनुभाग में अतिरिक्त भाषा पैक स्थापित करें।','%d locale pack installed.'=>'%d लोकल पैक स्थापित।' . "\0" . '%d लोकल पैक स्थापित।','Install a Language'=>'एक भाषा स्थापित करें','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'WordPress.org से सीधे वर्डप्रेस कोर भाषा पैक डाउनलोड और स्थापित करें। एक बार स्थापित हो जाने के बाद, लोकल URL रूटिंग और AI अनुवाद कार्यप्रवाह के लिए उपलब्ध हो जाती है। उपलब्ध भाषाओं की सूची आवश्यकतानुसार प्राप्त की जाती है — नीचे दिए गए बटन पर क्लिक करें।','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'इस सर्वर पर भाषा स्थापना अक्षम है। wp-config.php में DISALLOW_FILE_MODS स्थिरांक सेट है। भाषा पैक मैनुअल रूप से WP-CLI के माध्यम से स्थापित करें: wp language core install de_DE','Load available languages'=>'उपलब्ध भाषाएँ लोड करें','— select a language —'=>'— एक भाषा चुनें —','Install'=>'स्थापित करें','Language Setup'=>'भाषा सेटअप','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'कोई द्वितीयक भाषाएँ कॉन्फ़िगर नहीं हैं। टेम्प्लेट स्कैफ़ोल्डिंग सक्षम करने के लिए ऊपर एक भाषा पैक स्थापित करें।','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'उस भाषा का चयन करें ताकि उसकी FSE टेम्प्लेट, टेम्प्लेट भाग, और नेविगेशन मेनू का प्रबंधन किया जा सके।','Forbidden'=>'प्रतिबंधित','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'इस सर्वर पर भाषा स्थापना अक्षम है (DISALLOW_FILE_MODS सेट है)।','Invalid locale code.'=>'अमान्य लोकल कोड।','Language %s installed successfully.'=>'भाषा %s सफलतापूर्वक स्थापित।','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'भाषा पैक स्थापना विफल। भाषा पहले से ही स्थापित हो सकती है, लोकल कोड गलत हो सकता है, या आपका सर्वर फ़ाइल लेखन को ब्लॉक कर सकता है।','Navigations'=>'नेविगेशन','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'नेविगेशन अनुवाद के लिए एक सक्रिय AI प्रदाता आवश्यक है। API कुंजी को API Keys टैब में कॉन्फ़िगर करें।','Navigation'=>'नेविगेशन','Action'=>'क्रिया','Re-translate'=>'पुनः अनुवाद करें','CPT Block Patterns'=>'CPT ब्लॉक पैटर्न','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'कस्टम पोस्ट टाइप्स के लिए पंजीकृत ब्लॉक पैटर्न। भाषा संस्करण बनाने के लिए ट्रांसलेट बटन का उपयोग करें। अनुवादित सामग्री यहाँ सहेजी जाती है और ब्लॉक संपादक पैटर्न इंसर्टर से किसी भी CPT पोस्ट में कॉपी की जा सकती है या एक सिंक्ड पैटर्न (रीयूज़ेबल ब्लॉक) के लिए प्रारंभिक बिंदु के रूप में इस्तेमाल की जा सकती है।','Pattern'=>'पैटर्न','Post Types'=>'पोस्ट टाइप्स','✓ Translation saved'=>'✓ अनुवाद सहेजा गया','View'=>'देखें','Template Parts'=>'टेम्प्लेट भाग','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'थीम के टेम्प्लेट भागों की भाषा-विशिष्ट प्रतियाँ। एक बार स्कैफ़ोल्ड हो जाने के बाद, टेम्प्लेट भाषा-विशिष्ट भाग का संदर्भ देने के लिए अपडेट किए जाते हैं।','Part'=>'भाग','Status / Actions'=>'स्थिति / क्रियाएँ','Fix Links'=>'लिंक ठीक करें','Fix Nav'=>'नेविगेशन ठीक करें','Create'=>'बनाएँ','Templates'=>'टेम्प्लेट','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'सक्रिय थीम से बीजित FSE टेम्प्लेट। साइट संपादक में बनाएं और कस्टमाइज़ करें।','Actions'=>'क्रियाएँ','Fix Parts'=>'भाग ठीक करें','Create missing'=>'गुम हुई चीज़ बनाएँ','Translate all'=>'सभी का अनुवाद करें','Fix all parts'=>'सभी भागों को ठीक करें','Fix all links'=>'सभी लिंक ठीक करें','Anthropic (Claude)'=>'एंथ्रोपिक (क्लोड)','OpenAI (GPT)'=>'ओपनएआई (जीपीटी)','Google (Gemini)'=>'गूगल (जेमिनी)','Testing…'=>'परीक्षण हो रहा है…','✓ Connection OK'=>'✓ कनेक्शन ठीक है','✗ Failed:'=>'✗ असफल:,','No response from provider — check the error log for details.'=>'प्रदाता से प्रतिक्रिया नहीं मिली — विवरण के लिए त्रुटि लॉग जांचें।','Network error — could not reach the WordPress AJAX endpoint.'=>'नेटवर्क त्रुटि — वर्डप्रेस AJAX एंडपॉइंट तक नहीं पहुंच सका।','Loading…'=>'लोड हो रहा है…','Installing…'=>'इंस्टॉल हो रहा है…','✓ Language installed.'=>'✓ भाषा स्थापित।','✗ Error:'=>'✗ त्रुटि:','Creating…'=>'बनाया जा रहा है…','✓ All templates created.'=>'✓ सभी टेम्पलेट बनाए गए।','Some templates could not be created.'=>'कुछ टेम्पलेट नहीं बन सके।','✓ All parts created.'=>'✓ सभी भाग बनाए गए।','Some parts could not be created.'=>'कुछ भाग नहीं बन सके।','✓ All translated.'=>'✓ सभी अनुवादित।','Some translations failed.'=>'कुछ अनुवाद असफल रहे।','Review carefully — links and slugs not updated.'=>'सावधानीपूर्वक समीक्षा करें — लिंक और स्लग अपडेट नहीं किए गए।','Fixing…'=>'ठीक किया जा रहा है…','✓ Links fixed.'=>'✓ लिंक ठीक किए गए।','Some link fixes failed.'=>'कुछ लिंक सुधार असफल रहे।','✓ Parts fixed.'=>'✓ भाग ठीक किए गए।','Some part fixes failed.'=>'कुछ भाग सुधार असफल रहे।','✓ Nav refs fixed.'=>'✓ नेविगेशन संदर्भ ठीक किए गए।','Some nav ref fixes failed.'=>'कुछ नेविगेशन संदर्भ सुधार असफल रहे।','✓ Pattern translated.'=>'✓ पैटर्न का अनुवाद किया गया।','Pattern translation failed.'=>'पैटर्न अनुवाद असफल रहा।','Hide'=>'छुपाएँ','Built-in preset instructions:'=>'इन-बिल्ट प्रीसेट निर्देश:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'कोई इन-बिल्ट निर्देश नहीं — प्रत्येक AI सुविधा अपने ट्यून किए गए डिफ़ॉल्ट का उपयोग करती है। नीचे कस्टम प्रॉम्प्ट निर्देश फ़ील्ड भरें ताकि आप अपनी साइट-व्यापी नियम जोड़ सकें।','Settings'=>'सेटिंग्स','You do not have permission to manage these settings.'=>'आपके पास इन सेटिंग्स का प्रबंधन करने की अनुमति नहीं है।','Lingua Forge — Settings'=>'लिंगुआ फोर्ज — सेटिंग्स','Settings saved.'=>'सेटिंग्स सहेजी गई।','Save Settings'=>'सेटिंग्स सहेजें','Standard'=>'मानक','Technical / Scientific'=>'तकनीकी / वैज्ञानिक','Legal / Compliance'=>'कानूनी / अनुपालन','Creative / Marketing'=>'रचनात्मक / विपणन','Full Article'=>'पूर्ण लेख','Introduction only'=>'केवल परिचय','Structured Outline'=>'संरचित रूपरेखा','Generate Content'=>'सामग्री उत्पन्न करें','Hints'=>'संकेत','Key points, ideas, or structure to build from…'=>'मुख्य बिंदु, विचार, या संरचना से शुरू करें…','Tone'=>'स्वर','Output'=>'आउटपुट','Generate Excerpt'=>'अंश उत्पन्न करें','Generate Meta Description'=>'मेटा विवरण उत्पन्न करें','Translate Content'=>'सामग्री का अनुवाद करें','Mode'=>'मोड','Full post'=>'पूरा पोस्ट','Translate chunk'=>'टुकड़ा अनुवाद करें','Target Language'=>'लक्ष्य भाषा','Text to translate'=>'अनुवाद के लिए पाठ','Paste a footnote, sentence, or any snippet here…'=>'यहां फुटनोट, वाक्य, या कोई भी अंश चिपकाएं…','Also generate meta description'=>'मेटा विवरण भी उत्पन्न करें','Translated Names'=>'अनुवादित नाम','Name displayed in this language. Leave empty to use the source name.'=>'इस भाषा में प्रदर्शित नाम। स्रोत नाम का उपयोग करने के लिए खाली छोड़ दें।','Too many AI requests. Please retry in %d seconds.'=>'बहुत अधिक AI अनुरोध। कृपया %d सेकंड में पुनः प्रयास करें।','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'दैनिक AI कोटा पूरा हो गया (%1$d अनुरोध)। यह %2$s UTC पर रीसेट होता है।','View Lingua Forge details'=>'लिंगुआ फोर्ज विवरण देखें','View details'=>'विवरण देखें','Visit plugin site'=>'प्लगइन साइट पर जाएं','%d language not yet linked'=>'%d भाषा अभी तक लिंक नहीं है' . "\0" . '%d भाषाएं अभी तक लिंक नहीं हैं','This is the source page. Footnotes are edited directly in the block editor.'=>'यह स्रोत पृष्ठ है। फुटनोट सीधे ब्लॉक संपादक में संपादित किए जाते हैं।','No source page linked yet.'=>'अभी तक कोई स्रोत पृष्ठ लिंक नहीं है।','The source page has no footnotes.'=>'स्रोत पृष्ठ में कोई फुटनोट नहीं है।','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'ये फुटनोट स्रोत पृष्ठ से आते हैं और केवल संदर्भ के लिए यहां दिखाए गए हैं। इन्हें इस पृष्ठ में ब्लॉक संपादक का उपयोग करके जोड़ें।','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>लिंगुआ फोर्ज:</strong> %1$d स्थानीयकृत टेम्प्लेट(स) &#8220;%2$s&#8221; थीम से डेटाबेस में संरक्षित हैं लेकिन वर्तमान में निष्क्रिय हैं। यदि आप उस थीम को पुनः सक्रिय करते हैं तो वे फिर से सक्रिय हो जाएंगे। अपनी अनुवादों को नई थीम पर ले जाने के लिए, उन्हें <strong>सेटिंग्स → लिंगुआ फोर्ज → राउटर → FSE स्कैफोल्ड</strong> के माध्यम से पुनः जेनरेट करें।','Scanning posts for broken language links…'=>'भाषा लिंक टूटने के लिए पोस्ट स्कैन कर रहे हैं…','Re-scanning…'=>'पुनः स्कैन कर रहे हैं…','Scan failed: '=>'स्कैन विफल: ','unknown error'=>'अज्ञात त्रुटि','Scan request failed. Please try again.'=>'स्कैन अनुरोध विफल। कृपया पुनः प्रयास करें।','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ कोई <strong>{lang}</strong> पोस्ट नहीं मिली। सुनिश्चित करें कि सभी अनुवादित पोस्ट में उनकी भाषा मेटा <strong>{lang}</strong> पर सेट हो।','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ <strong>{lang}</strong> के लिए कोई टूटा लिंक या टेम्प्लेट मेल नहीं मिला। स्कैन किए गए <strong>{scanned}</strong> पोस्ट और पृष्ठ — सभी जांच पास। टेम्प्लेट भाग लिंक (हेडर, फुटर, साइडबार) यहां शामिल नहीं हैं — उन्हें अलग से जांचने के लिए फिक्स टेम्प्लेट पार्ट्स बटन का उपयोग करें।','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> स्वचालित रूप से ठीक करने योग्य लिंक','<strong>{n}</strong> link(s) needing manual review'=>'मैनुअल समीक्षा की आवश्यकता वाले <strong>{n}</strong> लिंक','and'=>'और','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'<strong>{total}</strong> में से <strong>{scanned}</strong> स्कैन किए गए पोस्ट के बीच {parts} पाया गया।','Post'=>'पोस्ट','Links'=>'लिंक','link(s)'=>'लिंक','Fix'=>'ठीक करें','✅ Fixed ({n})'=>'✅ ठीक किया ({n})','⚠ No changes — re-scan?'=>'⚠ कोई परिवर्तन नहीं — पुनः स्कैन करें?','⚠ No changes'=>'⚠ कोई परिवर्तन नहीं','❌ Failed'=>'❌ विफल','Done — {done} of {total} post(s) fixed.'=>'पूरा — {done} में से {total} पोस्ट ठीक की गई।','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} में कोई प्रतिस्थापन योग्य लिंक नहीं था — जांच के लिए पुनः स्कैन करें)','Fixing {n} / {total}…'=>'{n} / {total} को ठीक कर रहे हैं…','URL could not be mapped to a post — check the link target exists'=>'URL को पोस्ट से मैप नहीं किया जा सका — लिंक लक्ष्य मौजूद है या नहीं जांचें','No {lang} translation registered (TRID missing)'=>'कोई {lang} अनुवाद पंजीकृत नहीं है (TRID गायब)','Translation found but permalink could not be generated'=>'अनुवाद मिला लेकिन permalink उत्पन्न नहीं किया जा सका','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> पुराना पथ(आम','📍 Stale path (page moved)'=>'📍 पुराना पथ (पृष्ठ स्थानांतरित)','{n} stale path(s)'=>'{n} पुराना पथ(आम','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> टेम्पलेट समस्या(ए)','📄 Wrong template'=>'📄 गलत टेम्पलेट','Expected: {expected}'=>'अपेक्षित: {expected}','Current: {current}'=>'वर्तमान: {current}','Template "{expected}" does not exist — create it in the Site Editor first.'=>'टेम्पलेट "{expected}" मौजूद नहीं है — पहले इसे साइट संपादक में बनाएं।','Fix Template'=>'टेम्पलेट ठीक करें','✅ Template fixed'=>'✅ टेम्पलेट ठीक किया गया','Internal Link Fixer'=>'आंतरिक लिंक सुधारक','Fix All'=>'सभी ठीक करें','Re-scan'=>'पुनः स्कैन करें','Language Switcher'=>'भाषा स्विचर','Displays the Lingua Forge language switcher.'=>'लिंगुआ फोर्ज भाषा स्विचर प्रदर्शित करता है।','Language'=>'भाषा','Display'=>'प्रदर्शन','Language label'=>'भाषा लेबल','Icon only'=>'केवल आइकन','Icon + label'=>'आइकन + लेबल','Dropdown direction'=>'ड्रॉपडाउन दिशा','Down'=>'नीचे','Up'=>'ऊपर','You do not have permission to read this post.'=>'आपके पास इस पोस्ट को पढ़ने की अनुमति नहीं है।','Post not found.'=>'पोस्ट नहीं मिली।','Limit results to pages in the given Lingua Forge language code.'=>'दी गई लिंगुआ फोर्ज भाषा कोड में पृष्ठों के परिणाम सीमित करें।','Meta Description'=>'मेटा विवरण','Using custom meta description.'=>'कस्टम मेटा विवरण का उपयोग कर रहा है।','Prefilled from excerpt. Edit to override.'=>'अग्रिम से भरा हुआ है। ओवरराइड करने के लिए संपादित करें।','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'120–160 वर्णों का लक्ष्य रखें। फॉलबैक के रूप में उपयोग करने के लिए खाली छोड़ दें।','↺ Refreshing…'=>'↺ ताज़ा हो रहा है…','Review translation before applying'=>'लागू करने से पहले अनुवाद की समीक्षा करें','Current title'=>'वर्तमान शीर्षक','Translated title'=>'अनुवादित शीर्षक','Current content (will be overwritten)'=>'वर्तमान सामग्री (ओवरराइट की जाएगी)','Translated content'=>'अनुवादित सामग्री','Footnotes payload (advanced)'=>'फुटनोट्स पेलोड (उन्नत)','Generated meta description'=>'निर्मित मेटा विवरण','Saved to the meta description field when you apply.'=>'जब आप लागू करते हैं तो मेटा विवरण क्षेत्र में सहेजा जाता है।','Cancel'=>'रद्द करें','Apply translation'=>'अनुवाद लागू करें','Generated Content'=>'निर्मित सामग्री','Refine further:'=>'अधिक परिष्कृत करें:','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'ड्राफ्ट में सुधार करने के लिए निर्देश जोड़ें — जैसे कि इसे छोटा बनाएं, निष्कर्ष अनुभाग जोड़ें, अधिक औपचारिक रजिस्टर का उपयोग करें, FAQ ब्लॉक शामिल करें…','↺ Refine'=>'↺ परिष्कृत करें','Copy markup'=>'मार्कअप कॉपी करें','Apply to Editor'=>'संपादक में लागू करें','Copied ✓'=>'कॉपी किया ✓','Applying…'=>'लागू किया जा रहा है…','Applied ✓'=>'लागू ✓','Refining…'=>'सुधार रहा है…','Refinement failed — please try again.'=>'सुधार असफल रहा — कृपया पुनः प्रयास करें।','Refinement'=>'सुधार','✓ Refined — review the updated draft above.'=>'✓ सुधारा गया — ऊपर दिए गए मसौदे की समीक्षा, संशोधन और लागू करने के लिए देखें।','Request failed — please try again.'=>'अनुरोध असफल रहा — कृपया पुनः प्रयास करें।','The editor did not accept the content — please try again.'=>'संपादक ने सामग्री को स्वीकार नहीं किया — कृपया पुनः प्रयास करें।','Save the post to persist changes.'=>'परिवर्तनों को स्थायी बनाने के लिए पोस्ट सहेजें।','Apply failed — please try again.'=>'लागू करने में असफल — कृपया पुनः प्रयास करें।','Copy'=>'कॉपी','Apply to Meta Description'=>'मेटा विवरण पर लागू करें','Generating…'=>'सृजन हो रहा है…','Generation failed.'=>'सृजन असफल रहा।','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ सामग्री बनाई गई — समीक्षा, संशोधन और लागू करने के लिए ओवरले देखें।','Request failed.'=>'अनुरोध असफल रहा।','cached'=>'कैश्ड','Translated to:'=>'अनुवादित:','tone'=>'स्वर','Content generated'=>'सामग्री बनाई गई','Content ready'=>'सामग्री तैयार है','footnote(s) translated — applied together with content.'=>'अनुवादित फुटनोट(s) — सामग्री के साथ लागू किया गया।','Chunk translated to:'=>'अनुवादित खंड:','Chunk translated'=>'खंड का अनुवाद किया गया','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'परिणाम को कॉपी करें और जहां आवश्यक हो वहां चिपकाएं (जैसे सीधे फुटनोट फ़ील्ड में)।','chars'=>'अक्षर','✓ Good length'=>'✓ अच्छा लंबाई','⚠ Borderline'=>'⚠ सीमा रेखा','✗ Too short'=>'✗ बहुत छोटा','✗ Too long'=>'✗ बहुत लंबा','Target: 140–160 chars for optimal SERP display'=>'लक्ष्य: 140–160 अक्षर अनुकूल SERP प्रदर्शन के लिए','SEO character-count info'=>'एसईओ अक्षर गणना जानकारी','↺ Refresh'=>'↺ ताज़ा करें','Re-generates and updates the cached result.'=>'कैश किए गए परिणाम को पुनः जेनरेट और अपडेट करता है।','← Back'=>'← वापस','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'मसौदे में सुधार के लिए निर्देश जोड़ें — जैसे इसे छोटा बनाना, निष्कर्ष अनुभाग जोड़ना, अधिक औपचारिक रजिस्टर का उपयोग करना…','Improve writing'=>'लेखन में सुधार करें','Make formal'=>'औपचारिक बनाएं','Make casual'=>'आधिकारिक बनाएं','Make concise'=>'संक्षिप्त बनाएं','Expand'=>'विस्तार करें','Bulletize (•-prefixed)'=>'बुलेट करें (•-प्रारंभिक)','Lead paragraph (≤60 w)'=>'प्रमुख पैराग्राफ (≤60 शब्द)','Mark citations needed'=>'उद्धरण आवश्यक चिह्नित करें','Plain language'=>'सामान्य भाषा','Translate / Revise'=>'अनुवाद / संशोधन','Translate / Revise block'=>'संशोधन ब्लॉक','Revision'=>'समीक्षा','Footnotes'=>'फुटनोट','Block Content'=>'ब्लॉक सामग्री','Revision Type'=>'समीक्षा प्रकार','Revise'=>'समीक्षा','Footnote Content'=>'टिप्पणी सामग्री','Apply to Block'=>'ब्लॉक पर लागू करें','Instructions (optional)'=>'निर्देश (वैकल्पिक)','Extra guidance — tone, style, constraints, target audience…'=>'अतिरिक्त मार्गदर्शन — टोन, शैली, प्रतिबंध, लक्षित दर्शक…','Extra guidance — tone, style, constraints…'=>'अतिरिक्त मार्गदर्शन — टोन, शैली, प्रतिबंध…','↑ Detected from current post'=>'↑ वर्तमान पोस्ट से पता चला','Processing…'=>'प्रक्रिया में…','Failed. Please try again.'=>'असफल। कृपया पुनः प्रयास करें।','Request failed. Check your connection.'=>'अनुरोध असफल। अपना कनेक्शन जांचें।','Apply to Footnote'=>'टिप्पणी पर लागू करें','Quick Translate'=>'त्वरित अनुवाद','Paste text, or select text in the editor first…'=>'पाठ चिपकाएँ, या पहले संपादक में पाठ चुनें…','Clear input'=>'इनपुट साफ़ करें','Clear'=>'साफ़ करें','Instructions / key points'=>'निर्देश / मुख्य बिंदु','Describe what to write — topic, key points, structure…'=>'क्या लिखना है — विषय, मुख्य बिंदु, संरचना…','Language (optional)'=>'भाषा (वैकल्पिक)','— auto-detect —'=>'— स्वचालित पता लगाएँ —','Generate'=>'सृजन करें','Clear hints'=>'संकेत साफ़ करें','Clear All'=>'सभी साफ़ करें','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'अधिक परिष्कृत करें — जैसे "इसे छोटा करें" या "औपचारिक टोन का उपयोग करें"…','Please enter some text first…'=>'कृपया पहले कुछ टेक्स्ट दर्ज करें…','Please enter some instructions first…'=>'कृपया पहले कुछ निर्देश दर्ज करें…','Request failed. Please try again.'=>'अनुरोध असफल। कृपया पुनः प्रयास करें।','Tone:'=>'स्वर:','Language:'=>'भाषा:','Done'=>'पूर्ण','Lingua Forge AI Tools'=>'लिंगुआ फोर्ज एआई टूल्स','Close popover'=>'पॉपओवर बंद करें','Paste text, or select text on the page first…'=>'पाठ चिपकाएँ, या पहले पृष्ठ पर पाठ चुनें…','Result will appear here…'=>'परिणाम यहाँ दिखाई देगा…','Notice settings'=>'सूचना सेटिंग्स','Notice message'=>'सूचना संदेश','Shown when no translation exists for the visitor\'s language.'=>'जब कोई अनुवाद आगंतुक की भाषा के लिए मौजूद नहीं होता है तो दिखाया जाता है।','Show home link'=>'होम लिंक दिखाएँ','Adds a link to the home page so visitors can browse in their language.'=>'ऐसे लिंक जोड़ता है ताकि आगंतुक अपनी भाषा में ब्राउज़ कर सकें।','Home link text'=>'होम लिंक टेक्स्ट','block titleMissing Translation Notice'=>'अनुवाद अनुपस्थित सूचना','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'जब वर्तमान पृष्ठ अपनी स्रोत भाषा में दिखाया जा रहा हो क्योंकि आगंतुक की भाषा के लिए कोई अनुवाद मौजूद नहीं है, तो यह विनम्र सूचना दिखाता है। यह Lingua Forge राउटर के LINGUAFORGE_LANG_FALLBACK_ACTIVE सिग्नल द्वारा संचालित है — जब अनुरोध क्षेत्र के लिए कोई अनुवाद मौजूद हो तो कुछ भी नहीं उत्सर्जित करता है।','block keywordlanguage'=>'भाषा','block keywordtranslation'=>'अनुवाद','block keywordfallback'=>'फॉलबैक','block keywordi18n'=>'i18n','block keywordlinguaforge'=>'लिंगुआ फोर्ज']];
